const DAY = 864e5, now = Date.now();
const all = $input.all().map(i => i.json);
const inRange = (r, from, to) => { const t = new Date(r.posted_at).getTime(); return t >= now - from * DAY && t < now - to * DAY; };
const tally = (rows) => {
  const real = rows.filter(r => r.intent !== 'spam');
  const by = (k) => real.reduce((a, r) => (a[r[k]] = (a[r[k]] || 0) + 1, a), {});
  const pos = real.filter(r => r.sentiment === 'positive').length;
  return { total: real.length, spam_excluded: rows.length - real.length, pct_positive: real.length ? Math.round(100 * pos / real.length) : 0,
    negative: real.filter(r => r.sentiment === 'negative').length, by_topic: by('topic'), by_source: by('source'),
    urgent: real.filter(r => String(r.urgent) === 'true').length,
    urgent_handled: real.filter(r => String(r.urgent) === 'true' && r.handled_by).length };
};
const thisWeek = all.filter(r => inRange(r, 7, 0));
const lastWeek = all.filter(r => inRange(r, 14, 7));
const negatives = thisWeek.filter(r => r.sentiment === 'negative' && r.intent !== 'spam')
  .map(r => `[${r.topic}] ${String(r.text).slice(0, 200)}`);
return [{ json: { this_week: tally(thisWeek), last_week: tally(lastWeek), negatives } }];

