const c = $('Counts').first().json;
const tw = c.this_week, lw = c.last_week;
const topics = Object.entries(tw.by_topic).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(' · ');
const text = [
  'Harvest Lane · what customers said · last 7 days',
  `${tw.total} comments and reviews · ${tw.pct_positive}% positive (last week ${lw.pct_positive}%) · ${tw.negative} negative`,
  `Top topics: ${topics || 'none'}`,
  `${tw.urgent} urgent items, ${tw.urgent_handled} marked handled`,
  `${tw.spam_excluded} spam items excluded from the numbers`,
  '',
  'Three things to fix:',
  String($json.text || '').trim(),
].join('\n');
return [{ json: { text } }];
